-- Crayons Bridge RLS
-- Project: uakpqqardziifcwzvgfx ONLY.
-- Better Auth is the only application authentication system.
--
-- IMPORTANT:
-- Do not apply this file to production yet. The Bridge application connects
-- server-side through DATABASE_URL and authorizes requests in Better Auth + RBAC.
-- Supabase Auth's auth.uid() is therefore NOT the Bridge identity source.

alter table if exists public.bridge_profiles enable row level security;
alter table if exists public.bridge_titles enable row level security;
alter table if exists public.bridge_title_events enable row level security;
alter table if exists public.bridge_assets enable row level security;
alter table if exists public.bridge_payments enable row level security;
alter table if exists public.bridge_webhook_events enable row level security;
alter table if exists public.bridge_entitlements enable row level security;
alter table if exists public.bridge_audit_logs enable row level security;
alter table if exists public.bridge_email_challenges enable row level security;
alter table if exists public.bridge_invites enable row level security;

-- No anon/authenticated client policies are defined here intentionally.
-- Bridge data access is server-only and guarded by Better Auth session identity
-- plus src/lib/bridge/rbac.ts authorization checks.
--
-- Do not add auth.uid() policies unless Supabase Auth is intentionally adopted
-- for Bridge in a future architecture change.

-- Harden CRAYONS BRIDGE commercial engine to server-only database access.
-- Application authorization remains Better Auth + Bridge RBAC.
-- Data API roles must not have direct privileges on finance/commercial tables.

revoke all on table
  public.bridge_service_catalog,
  public.bridge_service_rates,
  public.bridge_tax_rates,
  public.bridge_service_quotes,
  public.bridge_service_quote_lines,
  public.bridge_service_orders,
  public.bridge_service_order_events,
  public.bridge_service_invoices,
  public.bridge_financial_ledger
from anon, authenticated;

grant select, insert, update, delete, references, trigger, truncate
on table
  public.bridge_service_catalog,
  public.bridge_service_rates,
  public.bridge_tax_rates,
  public.bridge_service_quotes,
  public.bridge_service_quote_lines,
  public.bridge_service_orders,
  public.bridge_service_order_events,
  public.bridge_service_invoices,
  public.bridge_financial_ledger
to service_role;

alter function public.bridge_service_margin_paise(uuid)
  set search_path = public, pg_temp;

revoke all on function public.bridge_service_margin_paise(uuid)
from public, anon, authenticated;

grant execute on function public.bridge_service_margin_paise(uuid)
to service_role;

-- CRAYONS BRIDGE commercial control plane: idempotency and reversal hardening.

alter table public.bridge_service_costs
  add column if not exists idempotency_key text;

create unique index if not exists bridge_service_costs_idempotency_uq
  on public.bridge_service_costs(idempotency_key)
  where idempotency_key is not null;

alter table public.bridge_financial_ledger
  drop constraint if exists bridge_financial_ledger_entry_type_check;

alter table public.bridge_financial_ledger
  add constraint bridge_financial_ledger_entry_type_check
  check (entry_type in (
    'REVENUE','INTERNAL_COST','PASS_THROUGH','TAX','PAYMENT_FEE',
    'REFUND','CHARGEBACK','CHARGEBACK_REVERSAL','SETTLEMENT'
  ));

-- Index the new commercial foreign keys used on high-frequency reconciliation paths.

create index if not exists bridge_financial_ledger_payment_idx
  on public.bridge_financial_ledger(payment_id, created_at desc);

create index if not exists bridge_service_costs_service_idx
  on public.bridge_service_costs(service_code, created_at desc);

create index if not exists bridge_service_orders_payment_idx
  on public.bridge_service_orders(payment_id);

create index if not exists bridge_service_quote_lines_rate_idx
  on public.bridge_service_quote_lines(rate_id);

create index if not exists bridge_service_quote_lines_service_idx
  on public.bridge_service_quote_lines(service_code);

create index if not exists bridge_service_settlement_lines_rule_idx
  on public.bridge_service_settlement_lines(rule_id);
